const RT_SYM = { fan: RT_DRAGON, rom: [[50, 32], [42, 22], [30, 20], [21, 29], [22, 43], [33, 57], [50, 74], [67, 57], [78, 43], [79, 29], [70, 20], [58, 22], [50, 32]], sus: Array.from({ length: 15 }, (_, i) => [50 + 30 * Math.cos(i / 14 * 6.283), 50 + 30 * Math.sin(i / 14 * 6.283)].map((v) => +v.toFixed(1))) };
const dragonSVG = (cls, th) => { const P = RT_SYM[th] || RT_DRAGON; return `<svg class="rtdr ${cls || ''}" viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><polyline points="${P.map((p) => p.join(',')).join(' ')}" pathLength="1"/>${P.map(([x, y], i) => `<circle cx="${x}" cy="${y}" r="${i === 0 ? 1.4 : 0.8}"/>`).join('')}</svg>`; };
